	b.WriteString("  \"summary_schema\": {\n")
	for i, key := range root.obj.keys {
		val, err := parseJSONRaw(root.obj.vals[key])
		if err != nil {
			return nil, err
		}
		writeSchemaField(&b, key, val, strict, 0, i == len(root.obj.keys)-1)
	}
	b.WriteString("  },\n")
	if ingestID != nil {
		writeSchemaKVString(&b, "ingest_id", *ingestID, 1, true)
	} else {
		writeSchemaKVRaw(&b, "ingest_id", "null", 1, true)
	}
	writeSchemaKVInt(&b, "run_index", runIndex, 1, true)
	scalar, obj, arr := countTopLevelTypes(root)
	b.WriteString("  \"field_summary\": {\n")
	b.WriteString(fmt.Sprintf("    \"array_fields\": %d,\n", arr))
	b.WriteString(fmt.Sprintf("    \"object_fields\": %d,\n", obj))
	b.WriteString(fmt.Sprintf("    \"scalar_fields\": %d\n", scalar))
	b.WriteString("  },\n")
	if strict {
		b.WriteString("  \"strict_mode\": true\n")
	} else {
		b.WriteString("  \"strict_mode\": false\n")
	}
	b.WriteString("}\n")
	return b.Bytes(), nil
}

func countTopLevelTypes(root *jsonValue) (scalar, obj, arr int) {
	for _, key := range root.obj.keys {
		val, err := parseJSONRaw(root.obj.vals[key])
		if err != nil {
			continue
		}
		switch val.typeString() {
		case "integer", "number", "string", "boolean", "null":
			scalar++
		case "object":
			obj++
		case "array":
			arr++
		}
	}
	return
}

func writeSchemaField(b *bytes.Buffer, key string, val *jsonValue, strict bool, depth int, last bool) {
	indent := strings.Repeat("  ", depth+2)
	b.WriteString(indent[:len(indent)-2])
	writeJSONString(b, key)
	b.WriteString(": {")
	b.WriteString(fmt.Sprintf("\n%s\"type\": \"%s\"", indent, val.typeString()))
	if val.isArr {
		var elemType string
		if len(val.arr) > 0 {
			ev, err := parseJSONRaw(val.arr[0])
			if err != nil {
				elemType = "null"
			} else {
				elemType = ev.typeString()
			}
		} else if strict {
			elemType = "unknown"
		}
		if len(val.arr) > 0 || !strict {
			b.WriteString(fmt.Sprintf(",\n%s\"element_type\": \"%s\"", indent, elemType))
		} else {
			b.WriteString(fmt.Sprintf(",\n%s\"element_type\": {\"type\": \"%s\"}", indent, elemType))
		}
	} else if val.isArr {
		b.WriteString(fmt.Sprintf(",\n%s\"element_type\": null", indent))
	}
	if val.isObj {
		b.WriteString(fmt.Sprintf(",\n%s\"fields\": [", indent))
		keys := append([]string(nil), val.obj.keys...)
		sort.Strings(keys)
		for i, k := range keys {
			if i > 0 {
				b.WriteString(", ")
			}
			writeJSONString(b, k)
		}
		b.WriteString("]")
	}
	b.WriteString(",\n" + indent + "\"constraints\": ")
	writeConstraints(b, val, strict, depth, indent)
	b.WriteString("\n" + indent[:len(indent)-2] + "}")
	if !last {
		b.WriteString(",")
	}
	b.WriteString("\n")
}

func writeConstraints(b *bytes.Buffer, val *jsonValue, strict bool, depth int, indent string) {
	b.WriteString("{")
	var entries []string
	var entryIndent string
	switch val.typeString() {
	case "integer":
		if n, ok := integerFromNumRaw(val.numRaw); ok {
			if n >= 0 {
				entries = append(entries, "\"non_negative\": true")
			}
			if strict && depth == 0 && n == 0 {
				entries = append(entries, "\"zero_observed\": true")
			}
		}
	case "number":
	case "string":
		if rfc3339UTCZRE.MatchString(val.strVal) {
			entries = append(entries, "\"format\": \"rfc3339-utc-z\"")
		}
	case "boolean", "null":
	case "object":
		entryIndent = indent + "  "
		keys := append([]string(nil), val.obj.keys...)
		sort.Strings(keys)
		entries = append(entries, fmt.Sprintf("\"field_count\": %d", len(keys)))
		if len(keys) > 0 && depth < 2 {
			subEntries := []string{}
			for _, k := range keys {
				ev, err := parseJSONRaw(val.obj.vals[k])
				if err != nil {
					continue
				}
				desc := buildDescriptorString(ev, strict, depth+1)
				subEntries = append(subEntries, fmt.Sprintf("\"%s\": %s", escapeJSONString(k), desc))
			}
			entries = append(entries, "\"subfields\": {"+strings.Join(subEntries, ", ")+"}")
		}
	case "array":
		entryIndent = indent + "  "
		if len(val.arr) > 0 {
			ev, err := parseJSONRaw(val.arr[0])
			if err == nil && ev.isObj && depth < 2 {
				keys := append([]string(nil), ev.obj.keys...)
				sort.Strings(keys)
				subEntries := []string{}
				for _, k := range keys {
					sv, err := parseJSONRaw(ev.obj.vals[k])
					if err != nil {
						continue
					}
					desc := buildDescriptorString(sv, strict, depth+1)
					subEntries = append(subEntries, fmt.Sprintf("\"%s\": %s", escapeJSONString(k), desc))
				}
				if len(subEntries) > 0 {
					entries = append(entries, "\"element_subfields\": {"+strings.Join(subEntries, ", ")+"}")
				}
			}
		}
		homogeneous := true
		if len(val.arr) == 0 {
			homogeneous = !strict
		} else {
			firstType := val.typeString()
			for _, r := range val.arr {
				ev, err := parseJSONRaw(r)
				if err != nil || ev.typeString() != firstType {
					homogeneous = false
					break
				}
			}
		}
		entries = append(entries, fmt.Sprintf("\"homogeneous\": %t", homogeneous))
		entries = append(entries, fmt.Sprintf("\"length\": %d", len(val.arr)))
	}
	if len(entries) == 0 {
		b.WriteString("}")
		return
	}
	if entryIndent == "" {
		entryIndent = indent + "  "
	}
	for i, e := range entries {
		if i > 0 {
			b.WriteString(",")
		}
		b.WriteString("\n" + entryIndent + e)
	}
	b.WriteString("\n" + indent + "}")
}

func buildDescriptorString(val *jsonValue, strict bool, depth int) string {
	var b bytes.Buffer
	b.WriteString("{")
	b.WriteString(fmt.Sprintf("\"type\": \"%s\"", val.typeString()))
	if val.isArr {
		var elemType string
		if len(val.arr) > 0 {
			ev, err := parseJSONRaw(val.arr[0])
			if err != nil {
				elemType = "null"
			} else {
				elemType = ev.typeString()
			}
		} else if strict {
			elemType = "unknown"
		}
		if len(val.arr) > 0 || !strict {
			b.WriteString(fmt.Sprintf(", \"element_type\": \"%s\"", elemType))
		} else {
			b.WriteString(fmt.Sprintf(", \"element_type\": {\"type\": \"%s\"}", elemType))
		}
	}
	if val.isObj {
		b.WriteString(", \"fields\": [")
		keys := append([]string(nil), val.obj.keys...)
		sort.Strings(keys)
		for i, k := range keys {
			if i > 0 {
				b.WriteString(", ")
			}
			writeJSONString(b, k)
		}
		b.WriteString("]")
	}
	b.WriteString(", \"constraints\": ")
	var c bytes.Buffer
	writeConstraints(&c, val, strict, depth, "")
	b.WriteString(c.String())
	b.WriteString("}")
	return b.String()
}

func writeSummarySchemaDigest(cfg cliConfig, schemaBytes []byte) error {
	root, err := parseJSONValue(schemaBytes)
	if err != nil {
		return err
	}
	fieldCount := 0
	if root.isObj {
		if ss, ok := root.obj.vals["summary_schema"]; ok {
			ssv, err := parseJSONRaw(ss)
			if err == nil && ssv.isObj {
				fieldCount = len(ssv.obj.keys)
			}
		}
	}
	out := struct {
		SchemaPath   string `json:"schema_path"`
		SchemaSHA256 string `json:"schema_sha256"`
		SchemaBytes  int   `json:"schema_bytes"`
		FieldCount   int   `json:"field_count"`
		ToolVersion   string `json:"tool_version"`
	}{
		SchemaPath:   filepath.Base(cfg.summarySchemaOut),
		SchemaSHA256: sha256Hex(schemaBytes),
		SchemaBytes:  len(schemaBytes),
		FieldCount:   fieldCount,
		ToolVersion:  toolVersion,
	}
	data, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	return atomicWriteFile(cfg.summarySchemaDigest, data)
}

func writeSummarySchemaIndex(cfg cliConfig, schemaBytes []byte) error {
	root, err := parseJSONValue(schemaBytes)
	if err != nil {
		return err
	}
	entries := []map[string]string{}
	if root.isObj {
		if ss, ok := root.obj.vals["summary_schema"]; ok {
			ssv, err := parseJSONRaw(ss)
			if err == nil && ssv.isObj {
				for _, key := range ssv.obj.keys {
					fv, err := parseJSONRaw(ssv.obj.vals[key])
					if err != nil {
						continue
					}
					entries = append(entries, map[string]string{"name": key, "type": fv.typeString(), "path": "$." + key})
					if fv.isArr && len(fv.arr) > 0 {
						ev, err := parseJSONRaw(fv.arr[0])
						if err == nil && ev.isObj {
							keys := append([]string(nil), ev.obj.keys...)
							sort.Strings(keys)
							for _, k := range keys {
								entries = append(entries, map[string]string{"name": k, "type": ev.typeString(), "path": "$." + key + "[*]." + k})
							}
						}
					}
				}
			}
		}
	}
	var b bytes.Buffer
	b.WriteString("{\n")
	b.WriteString("  \"entries\": [\n")
	for i, e := range entries {
		b.WriteString("    {")
		b.WriteString(fmt.Sprintf("\"name\": \"%s\", ", escapeJSONString(e["name"])))
		b.WriteString(fmt.Sprintf("\"type\": \"%s\", ", escapeJSONString(e["type"])))
		b.WriteString(fmt.Sprintf("\"path\": \"%s\"", escapeJSONString(e["path"])))
		b.WriteString("}")
		if i < len(entries)-1 {
			b.WriteString(",")
		}
		b.WriteString("\n")
	}
	b.WriteString("  ],\n")
	b.WriteString(fmt.Sprintf("  \"entry_count\": %d,\n", len(entries)))
	b.WriteString(fmt.Sprintf("  \"generated_from\": \"%s\",\n", escapeJSONString(filepath.Base(cfg.summarySchemaOut))))
	b.WriteString(fmt.Sprintf("  \"tool_version\": \"%s\"\n", toolVersion))
	b.WriteString("}\n")
	return atomicWriteFile(cfg.summarySchemaIndex, b.Bytes())
}

func writeSchemaKVString(b *bytes.Buffer, key, val string, indent int, comma bool) {
	prefix := strings.Repeat("  ", indent)
	b.WriteString(prefix)
	writeJSONString(b, key)
	b.WriteString(": ")
	writeJSONString(b, val)
	if comma {
		b.WriteString(",")
	}
	b.WriteString("\n")
}

func writeSchemaKVRaw(b *bytes.Buffer, key, raw string, indent int, comma bool) {
	prefix := strings.Repeat("  ", indent)
	b.WriteString(prefix)
	writeJSONString(b, key)
	b.WriteString(": ")
	b.WriteString(raw)
	if comma {
		b.WriteString(",")
	}
	b.WriteString("\n")
}

func writeSchemaKVInt(b *bytes.Buffer, key string, val int, indent int, comma bool) {
	prefix := strings.Repeat("  ", indent)
	b.WriteString(prefix)
	writeJSONString(b, key)
	b.WriteString(fmt.Sprintf(": %d", val))
	if comma {
		b.WriteString(",")
	}
	b.WriteString("\n")
}

func writeJSONString(b *bytes.Buffer, s string) {
	enc, err := json.Marshal(s)
	if err != nil {
		b.WriteString(fmt.Sprintf("\"%s\"", escapeJSONString(s)))
		return
	}
	b.Write(enc)
}

func escapeJSONString(s string) string {
	enc, err := json.Marshal(s)
	if err != nil {
		return s
	}
	return string(enc[1 : len(enc)-1])
}
