func newOrderedObject(entries ...orderedJSON) any {
	return entries
}

func orderedString(s string) any     { return s }
func orderedInt(n int) any           { return n }
func orderedInt64(n int64) any       { return n }
func orderedBool(b bool) any         { return b }
func orderedNull() any               { return nil }

func writeOrderedValue(buf *bytes.Buffer, v any) {
