}

func writeOrderedIndentValue(buf *bytes.Buffer, v any, indent int) {
	switch val := v.(type) {
	case []orderedJSON:
		writeOrderedIndentObject(buf, val, indent)
	case orderedArray:
		writeOrderedIndentArrayAny(buf, val, indent)
	case []any:
		writeOrderedIndentArrayAny(buf, val, indent)
	case string:
		writeJSONString(buf, val)
	case int:
		fmt.Fprintf(buf, "%d", val)
	case int64:
		fmt.Fprintf(buf, "%d", val)
