		if val {
			buf.WriteString("true")
		} else {
			buf.WriteString("false")
		}
	case nil:
		buf.WriteString("null")
	case orderedJSON:
		writeOrderedIndentValue(buf, val.value, indent)
	default:
		b, _ := json.Marshal(val)
		buf.Write(b)
	}
}

func writeOrderedIndentObject(buf *bytes.Buffer, entries []orderedJSON, indent int) {
	if len(entries) == 0 {
		buf.WriteString("{}")
		return
	}
	buf.WriteByte('{')
	buf.WriteByte('\n')
	for i, e := range entries {
		writeIndent(buf, indent+1)
		writeJSONString(buf, e.key)
		buf.WriteString(": ")
		writeOrderedIndentValue(buf, e.value, indent+1)
		if i < len(entries)-1 {
			buf.WriteByte(',')
		}
		buf.WriteByte('\n')
	}
	writeIndent(buf, indent)
	buf.WriteByte('}')
}

func writeOrderedIndentArrayAny(buf *bytes.Buffer, arr []any, indent int) {
	if len(arr) == 0 {
		buf.WriteString("[]")
		return
