	buf.WriteByte('[')
	buf.WriteByte('\n')
	for i, v := range arr {
		writeIndent(buf, indent+1)
		writeOrderedIndentValue(buf, v, indent+1)
		if i < len(arr)-1 {
			buf.WriteByte(',')
		}
		buf.WriteByte('\n')
	}
	writeIndent(buf, indent)
	buf.WriteByte(']')
}

func writeIndent(buf *bytes.Buffer, indent int) {
	for i := 0; i < indent; i++ {
		buf.WriteString("  ")
	}
}

func marshalOrderedIndent(v any) []byte {
	var buf bytes.Buffer
	writeOrderedIndent(&buf, v, 0)
	return buf.Bytes()
}

type summaryField struct {
	key   string
	value any
}

func parseSummaryFields(data []byte) ([]summaryField, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	tok, err := dec.Token()
	if err != nil {
		return nil, err
	}
	delim, ok := tok.(json.Delim)
	if !ok || delim != '{' {
		return nil, fmt.Errorf("summary output is not a JSON object")
	}
	var fields []summaryField
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		key, ok := keyTok.(string)
		if !ok {
			return nil, fmt.Errorf("summary object key is not a string")
		}
		var val any
		if err := dec.Decode(&val); err != nil {
			return nil, err
		}
		fields = append(fields, summaryField{key: key, value: val})
	}
	if _, err := dec.Token(); err != nil {
		return nil, err
	}
	return fields, nil
}

func classify(v any) string {
	switch val := v.(type) {
	case nil:
		return "null"
	case bool:
		return "boolean"
	case string:
		return "string"
	case json.Number:
		s := val.String()
		if !strings.ContainsAny(s, ".eE") {
			return "integer"
		}
		return "number"
	case float64:
		if val == float64(int64(val)) {
			return "integer"
		}
		return "number"
	case []any:
		return "array"
	case map[string]any:
		return "object"
	default:
		return "unknown"
	}
}

func descriptorFor(v any, depth int, strict bool) []orderedJSON {
	t := classify(v)
	entries := []orderedJSON{{key: "type", value: t}}
	switch t {
	case "array":
		arr := v.([]any)
		var elementType any
		if len(arr) == 0 {
			if strict {
				elementType = []orderedJSON{{key: "type", value: "unknown"}}
			} else {
				elementType = nil
			}
		} else {
			elementType = classify(arr[0])
		}
		entries = append(entries, orderedJSON{key: "element_type", value: elementType})
		entries = append(entries, orderedJSON{key: "constraints", value: arrayConstraints(arr, depth, strict)})
	case "object":
		obj := v.(map[string]any)
		entries = append(entries, orderedJSON{key: "fields", value: sortedKeys(obj)})
		entries = append(entries, orderedJSON{key: "constraints", value: objectConstraints(obj, depth, strict)})
	default:
		entries = append(entries, orderedJSON{key: "constraints", value: scalarConstraints(v, t, depth, strict)})
	}
	return entries
}

func sortedKeys(obj map[string]any) []any {
	keys := make([]string, 0, len(obj))
	for k := range obj {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	arr := make([]any, len(keys))
	for i, k := range keys {
		arr[i] = k
	}
	return arr
}

func scalarConstraints(v any, t string, depth int, strict bool) []orderedJSON {
	var entries []orderedJSON
	switch t {
	case "integer":
		if isNonNegativeInteger(v) {
			entries = append(entries, orderedJSON{key: "non_negative", value: true})
		}
		if strict && depth == 0 && isZeroInteger(v) {
			entries = append(entries, orderedJSON{key: "zero_observed", value: true})
		}
	case "string":
		if isRFC3339UTCZ(v.(string)) {
			entries = append(entries, orderedJSON{key: "format", value: "rfc3339-utc-z"})
		}
	}
	return entries
}

func arrayConstraints(arr []any, depth int, strict bool) []orderedJSON {
	var entries []orderedJSON
	if len(arr) > 0 && classify(arr[0]) == "object" {
		if depth < 2 {
			entries = append(entries, orderedJSON{key: "element_subfields", value: elementSubfields(arr[0].(map[string]any), depth+1, strict)})
		}
	}
	homogeneous := true
	if len(arr) == 0 {
		homogeneous = !strict
	} else {
		first := classify(arr[0])
		for _, e := range arr[1:] {
			if classify(e) != first {
				homogeneous = false
				break
			}
		}
	}
	entries = append(entries, orderedJSON{key: "homogeneous", value: homogeneous})
	entries = append(entries, orderedJSON{key: "length", value: len(arr)})
	return entries
}

func objectConstraints(obj map[string]any, depth int, strict bool) []orderedJSON {
	entries := []orderedJSON{{key: "field_count", value: len(obj)}}
	if len(obj) > 0 && depth < 2 {
		entries = append(entries, orderedJSON{key: "subfields", value: subfields(obj, depth+1, strict)})
	}
	return entries
}

func subfields(obj map[string]any, depth int, strict bool) []orderedJSON {
	keys := make([]string, 0, len(obj))
	for k := range obj {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	entries := make([]orderedJSON, 0, len(keys))
	for _, k := range keys {
		entries = append(entries, orderedJSON{key: k, value: descriptorFor(obj[k], depth, strict)})
	}
	return entries
}

func elementSubfields(obj map[string]any, depth int, strict bool) []orderedJSON {
	return subfields(obj, depth, strict)
}

func isNonNegativeInteger(v any) bool {
	switch val := v.(type) {
	case json.Number:
		s := val.String()
		if strings.ContainsAny(s, ".eE") {
			return false
		}
		n, err := val.Int64()
		if err != nil {
			return false
		}
		return n >= 0
	case float64:
		if val != float64(int64(val)) {
			return false
		}
		return val >= 0
	}
	return false
}

func isZeroInteger(v any) bool {
	switch val := v.(type) {
	case json.Number:
		s := val.String()
		if strings.ContainsAny(s, ".eE") {
			return false
		}
		n, err := val.Int64()
		if err != nil {
			return false
		}
		return n == 0
	case float64:
		if val != float64(int64(val)) {
			return false
		}
		return val == 0
	}
	return false
}

func isRFC3339UTCZ(s string) bool {
	return rfc3339UTCZRE.MatchString(s)
}

func buildSchemaSidecar(summaryData []byte, cfg cliConfig, runIndex int) ([]byte, error) {
	fields, err := parseSummaryFields(summaryData)
	if err != nil {
		return nil, err
	}
	summarySchema := make([]orderedJSON, 0, len(fields))
	var arrayFields, objectFields, scalarFields int
	for _, f := range fields {
		t := classify(f.value)
		switch t {
		case "array":
			arrayFields++
		case "object":
			objectFields++
		default:
			scalarFields++
		}
		summarySchema = append(summarySchema, orderedJSON{key: f.key, value: descriptorFor(f.value, 0, cfg.summarySchemaStrict)})
	}
	var ingestID any
	if cfg.ingestIDSet {
		ingestID = cfg.ingestID
	} else {
		ingestID = nil
	}
	top := []orderedJSON{
		{key: "schema_version", value: summarySchemaVersion},
		{key: "summary_schema", value: summarySchema},
		{key: "ingest_id", value: ingestID},
		{key: "run_index", value: runIndex},
		{key: "field_summary", value: []orderedJSON{
			{key: "array_fields", value: arrayFields},
			{key: "object_fields", value: objectFields},
			{key: "scalar_fields", value: scalarFields},
		}},
		{key: "strict_mode", value: cfg.summarySchemaStrict},
	}
	data := marshalOrderedIndent(top)
	data = append(data, '\n')
	return data, nil
}

func writeSummarySchemaSidecars(cfg cliConfig, summaryData []byte, runIndex int) error {
	if cfg.summarySchemaOut == "" {
		return nil
	}
	schemaData, err := buildSchemaSidecar(summaryData, cfg, runIndex)
	if err != nil {
		return err
	}
	if err := atomicWriteFile(cfg.summarySchemaOut, schemaData); err != nil {
		return err
	}
	if cfg.summarySchemaDigest != "" {
		hash, n, err := fileDigest(cfg.summarySchemaOut)
		if err != nil {
			return err
		}
		digest := []orderedJSON{
			{key: "schema_path", value: filepath.Base(cfg.summarySchemaOut)},
			{key: "schema_sha256", value: hash},
			{key: "schema_bytes", value: n},
			{key: "field_count", value: 7},
			{key: "tool_version", value: toolVersion},
		}
		data := marshalOrderedIndent(digest)
		data = append(data, '\n')
		if err := atomicWriteFile(cfg.summarySchemaDigest, data); err != nil {
			return err
		}
		if cfg.summarySchemaIndex != "" {
			index, err := buildIndexSidecar(cfg, summaryData)
			if err != nil {
				return err
			}
			if err := atomicWriteFile(cfg.summarySchemaIndex, index); err != nil {
				return err
			}
		}
	}
	return nil
}

func buildIndexSidecar(cfg cliConfig, summaryData []byte) ([]byte, error) {
	fields, err := parseSummaryFields(summaryData)
	if err != nil {
		return nil, err
	}
	entries := make([]any, 0)
	for _, f := range fields {
		entries = append(entries, []orderedJSON{
			{key: "name", value: f.key},
			{key: "type", value: classify(f.value)},
			{key: "path", value: "$." + f.key},
		})
		if classify(f.value) == "array" {
			arr := f.value.([]any)
			if len(arr) > 0 && classify(arr[0]) == "object" {
				obj := arr[0].(map[string]any)
				keys := make([]string, 0, len(obj))
				for k := range obj {
					keys = append(keys, k)
				}
				sort.Strings(keys)
				for _, k := range keys {
					entries = append(entries, []orderedJSON{
						{key: "name", value: k},
						{key: "type", value: classify(obj[k])},
						{key: "path", value: fmt.Sprintf("$.%s[*].%s", f.key, k)},
					})
				}
			}
		}
	}
	top := []orderedJSON{
		{key: "entries", value: entries},
		{key: "entry_count", value: len(entries)},
		{key: "generated_from", value: filepath.Base(cfg.summarySchemaOut)},
		{key: "tool_version", value: toolVersion},
	}
	data := marshalOrderedIndent(top)
	data = append(data, '\n')
	return data, nil
}
